const raw = $input.first().json;
const b = raw.body ?? raw;
const AGENTS = { 3: 'Ana Gomez', 4: 'Beatriz Ruiz', 6: 'Carolina Diaz', 7: 'Diana Mejia' };
if (b.event && b.event !== 'conversation_updated') { return []; }
const conv = b.conversation ?? b;
const convId = conv.id;
if (!convId) { return []; }
const changed = b.changed_attributes ?? conv.changed_attributes;
if (Array.isArray(changed) && changed.length && !changed.some(c => Object.keys(c || {}).includes('assignee_id'))) { return []; }
const assignee = conv.meta?.assignee ?? b.assignee ?? null;
const assigneeId = assignee?.id ?? null;
const agente = AGENTS[assigneeId];
if (!agente) { return []; }
const accountId = b.account?.id ?? b.account_id ?? conv.account_id ?? 1;
const url = 'https://chatwoot.example.com/app/accounts/' + accountId + '/conversations/' + convId;
const phone = String(conv.meta?.sender?.phone_number ?? '').trim();
const digits = phone.replace(/[^0-9]/g, '');
const groups = [{ filters: [{ propertyName: 'conversation_transcript_url', operator: 'EQ', value: url }] }];
if (digits) {
  groups.push({ filters: [{ propertyName: 'whatsapp_id', operator: 'EQ', value: '+' + digits }] });
  groups.push({ filters: [{ propertyName: 'whatsapp_id', operator: 'EQ', value: digits }] });
  groups.push({ filters: [{ propertyName: 'phone', operator: 'EQ', value: '+' + digits }] });
}
return [{ json: { conversation_id: convId, account_id: accountId, assignee_id: assigneeId, agente: agente, transcript_url: url, phone: phone, searchBody: { filterGroups: groups, properties: ['agente', 'conversation_transcript_url', 'whatsapp_id', 'phone', 'firstname'], limit: 5 } } }];

const src = $('Normalizar evento').first().json;
const results = $input.first().json.results ?? [];
if (!results.length) { return []; }
const c = results[0];
const current = c.properties?.agente ?? null;
if (current === src.agente) { return []; }
return [{ json: { contact_id: c.id, agente: src.agente, agente_anterior: current, conversation_id: src.conversation_id } }];
